mapper.sql:
WHERE 1 = 1
AND swing_task_id = #{taskId}
AND channel_code = #{channelCode}
AND mapping_user_id = #{personCode}
AND person_name LIKE CONCAT('%', #{personName}, '%')
AND swing_time >= #{startTime}
AND swing_time <= #{endTime}
AND mapping_user_id IS NOT NULL AND mapping_user_id != ''
AND (open_result IS NULL OR open_result = 1)
